def _t():

    class C:

        def __enter__(self):
            return (1, 2, 3)

        def __exit__(self, t, v, tb):
            pass
    targets = {1: [0, 1, 2]}
    with C() as (targets[1][0], targets[1][1], targets[1][2]):
        assert targets == {1: [1, 2, 3]}, ('assertEqual', targets, {1: [1, 2, 3]})
    with C() as (list(targets.values())[0][2], list(targets.values())[0][1], list(targets.values())[0][0]):
        assert targets == {1: [3, 2, 1]}, ('assertEqual', targets, {1: [3, 2, 1]})
    with C() as (targets[1], targets[2], targets[3]):
        assert targets == {1: 1, 2: 2, 3: 3}, ('assertEqual', targets, {1: 1, 2: 2, 3: 3})

    class B:
        pass
    blah = B()
    with C() as (blah.one, blah.two, blah.three):
        assert blah.one == 1, ('assertEqual', blah.one, 1)
        assert blah.two == 2, ('assertEqual', blah.two, 2)
        assert blah.three == 3, ('assertEqual', blah.three, 3)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
